#!/usr/bin/env python3
"""Audit how much of the Nexus settings tree the search index can actually reach.

The index has two halves:

  `shell/modules/nexus/PageCompRegistry.qml`  categories, pages, and subpages
                                             with curated keywords
  `shell/modules/nexus/PageRowIndex.qml`     every setting row the pages render,
                                             generated by
                                             `tools/generate_settings_index.py`

A page, a section or a setting that neither half names is invisible to search,
and nothing else in CI notices: the QML still parses, the pages still render,
and the setting is still reachable by clicking through.

Hard gate (exits non-zero):
  every settings sub-page listed in PageCompRegistry must be a target of some
  index entry. Sub-pages that only render a device, network or app the user
  picked before are exempt - a search hit for those would open an empty page.

Reported, not gated:
  section headers. They are not rows, so no index entry can select one; the
  counts below are printed on every run so the gap stays visible.
"""

from __future__ import annotations

import importlib.util
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
NEXUS = ROOT / "shell" / "modules" / "nexus"
REGISTRY = NEXUS / "PageCompRegistry.qml"

LABEL = re.compile(r'label:\s*qsTr\("([^"]+)"\)')
KEYWORDS = re.compile(r'keywords:\s*\[([^\]]*)\]')
DESCRIPTION = re.compile(r'description:\s*qsTr\("([^"]+)"\)')
KEY = re.compile(r'key:\s*"([^"]+)"')

SETTING_BLOCKS = (
    "ToggleRow",
    "StepperRow",
    "DoubleStepperRow",
    "SelectRow",
    "TextFieldRow",
    "NavRow",
    "SliderRow",
)


def settings_index_module():
    """The generator, so the report measures the index the shell actually builds."""
    path = ROOT / "tools" / "generate_settings_index.py"
    spec = importlib.util.spec_from_file_location("generate_settings_index", path)
    module = importlib.util.module_from_spec(spec)
    assert spec.loader
    spec.loader.exec_module(module)
    return module


GENERATOR = settings_index_module()

# A sub-page that describes the object the user picked earlier cannot be opened
# from a query; the generator leaves its rows out for the same reason.
CONTEXT_DEPENDENT = GENERATOR.context_slots()

REPORT_LIMIT = 25


def normalise(text: str) -> str:
    """Lowercase and strip punctuation, keeping word boundaries."""
    spaced = "".join(char if char.isalnum() else " " for char in text.lower())
    return re.sub(r"\s+", " ", spaced).strip()


def registry_texts_and_targets() -> tuple[list[str], set[tuple[int, str]]]:
    """Mirror PageRegistry.buildIndex(): the strings a query is matched against and navigation targets."""
    texts: list[str] = []
    targets: set[tuple[int, str]] = set()

    content = REGISTRY.read_text(encoding="utf-8")
    cats = GENERATOR.extract_blocks(content, "Category")

    for cat_idx, cat in enumerate(cats):
        cat_label_match = LABEL.search(cat)
        cat_label = cat_label_match.group(1) if cat_label_match else ""
        cat_key_match = KEY.search(cat)
        cat_key = cat_key_match.group(1) if cat_key_match else ""
        cat_desc_match = DESCRIPTION.search(cat)
        cat_desc = cat_desc_match.group(1) if cat_desc_match else ""

        texts.append(f"{cat_label} {cat_desc} {cat_key}")
        targets.add((cat_idx, "hub"))

        pages = GENERATOR.extract_blocks(cat, "Page")
        for page in pages:
            pk_match = KEY.search(page)
            if not pk_match:
                continue
            pk = pk_match.group(1)
            plabel_match = LABEL.search(page)
            plabel = plabel_match.group(1) if plabel_match else ""
            pdesc_match = DESCRIPTION.search(page)
            pdesc = pdesc_match.group(1) if pdesc_match else ""
            pkw_match = KEYWORDS.search(page)
            pkw = re.findall(r'"([^"]+)"', pkw_match.group(1)) if pkw_match else []

            texts.append(" ".join([plabel, pdesc, cat_label] + pkw))
            targets.add((cat_idx, pk))

            for sub in GENERATOR.extract_blocks(page, "SubPage"):
                sk_match = KEY.search(sub)
                if not sk_match:
                    continue
                sk = sk_match.group(1)
                slabel_match = LABEL.search(sub)
                slabel = slabel_match.group(1) if slabel_match else ""
                skw_match = KEYWORDS.search(sub)
                skw = re.findall(r'"([^"]+)"', skw_match.group(1)) if skw_match else []

                texts.append(" ".join([slabel, plabel, cat_label] + skw))
                targets.add((cat_idx, sk))

    # Add generated rows from PageRowIndex
    for row in GENERATOR.collect_rows():
        targets.add((int(row["pageIdx"]), str(row["subPage"])))
        words = [str(row["label"]), str(row["description"] or ""), str(row["section"] or "")]
        texts.append(" ".join(w for w in words if w))

    return [normalise(t) for t in texts], targets


def registry_subpages() -> list[tuple[int, str, str]]:
    """Every sub-page, as (pageIdx, subPageKey, component name)."""
    slots = GENERATOR.component_slots()
    return [(page, slot, name) for name, targets in slots.items() for page, slot in targets]


def block_labels(block_type: str) -> list[tuple[str, str]]:
    """Labels rendered by a given component type, as (label, relative path)."""
    found: list[tuple[str, str]] = []
    for path in sorted((NEXUS / "pages").rglob("*.qml")):
        lines = path.read_text(encoding="utf-8").splitlines()
        for number, line in enumerate(lines, 1):
            if f"{block_type} {{" not in line:
                continue
            for offset in range(1, 12):
                index = number - 1 + offset
                if index >= len(lines):
                    break
                match = re.search(r'(?:text|label): qsTr\("([^"]+)"\)', lines[index])
                if match:
                    found.append((match.group(1), path.relative_to(NEXUS).as_posix()))
                    break
    return found


def setting_labels() -> list[tuple[str, str]]:
    found: list[tuple[str, str]] = []
    for block_type in SETTING_BLOCKS:
        found += block_labels(block_type)
    return found


def is_subsequence(needle: str, haystack: str) -> bool:
    position = 0
    for char in needle:
        position = haystack.find(char, position) + 1
        if position == 0:
            return False
    return True


def reached(label: str, index: list[str]) -> bool:
    """Matches a query as a subsequence of a candidate string."""
    needle = normalise(label)
    return any(is_subsequence(needle, candidate) for candidate in index)


def named(label: str, index: list[str]) -> bool:
    """An entry actually names this label, rather than matching it by accident."""
    needle = normalise(label)
    return any(needle in candidate for candidate in index)


def report(title: str, rows: list[tuple[str, str]], index: list[str], qualify) -> None:
    print(f"\n== {title}: {len(rows)} of {qualify['total']}")
    for label, location in rows[:REPORT_LIMIT]:
        print(f"   {location:<44} {label}")
    if len(rows) > REPORT_LIMIT:
        print(f"   ... and {len(rows) - REPORT_LIMIT} more")


def main() -> int:
    index, targets = registry_texts_and_targets()

    subpages = registry_subpages()
    unreachable = [
        (page, sub, name)
        for page, sub, name in subpages
        if (page, sub) not in targets and (page, sub) not in CONTEXT_DEPENDENT
    ]

    settings = setting_labels()
    headers = block_labels("SectionHeader")
    excluded = GENERATOR.context_files()
    # Rows on a page that describes a picked object are not a search gap.
    settings = [row for row in settings if Path(row[1]).stem not in excluded]
    unnamed_settings = [row for row in settings if not named(row[0], index)]
    unnamed_headers = [row for row in headers if not named(row[0], index)]
    unreached_settings = [row for row in settings if not reached(row[0], index)]

    print("== Nexus search coverage ==")
    print(f"   index entries          {len(index)}")
    print(f"   settings sub-pages     {len(subpages)} ({len(CONTEXT_DEPENDENT)} context-dependent)")
    print(f"   section headers        {len(headers)}")
    print(f"   setting rows           {len(settings)}")

    report("Section headers no entry names", unnamed_headers, index, {"total": len(headers)})
    report("Setting rows no entry names", unnamed_settings, index, {"total": len(settings)})
    report("Setting rows no query can match", unreached_settings, index, {"total": len(settings)})

    if unreachable:
        print(f"\n[ERR] {len(unreachable)} settings sub-page(s) cannot be reached from search:")
        for page, sub, name in unreachable:
            print(f"   page {page} sub {sub}  {name}")
        print("   Add an entry for each to PageCompRegistry.qml, or list it in CONTEXT_DEPENDENT "
              "with the reason it cannot stand on its own.")
        return 1

    print("\n[OK] every settings sub-page is reachable from search")
    return 0


if __name__ == "__main__":
    sys.exit(main())
